"use client";

import { useCallback, useEffect, useState } from "react";
import { ArrowRight, ChevronLeft, ChevronRight, Pause, Play } from "lucide-react";
import { heroSlides } from "./data";
import { cn } from "@/lib/utils";

const AUTOPLAY_MS = 7000;

// Mobile variant generated by scripts/gen-images.mjs (same path, `-900w` suffix).
const variant = (src: string, width: number) => src.replace(/\.(\w+)$/, `-${width}w.$1`);


// Full-height slideshow of the Foundation's own photos, with a slow zoom on the
// active photo and a progress bar on the current dot. Autoplay pauses on hover
// and focus, has a pause button, and is off (with no zoom) for people who ask
// their device for reduced motion.
export function HeroSlider() {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovering, setHovering] = useState(false);
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const goTo = useCallback((i: number) => setIndex((i + heroSlides.length) % heroSlides.length), []);
  const running = !paused && !hovering && !reduced;

  useEffect(() => {
    if (!running) return;
    const t = setTimeout(() => goTo(index + 1), AUTOPLAY_MS);
    return () => clearTimeout(t);
  }, [index, running, goTo]);

  return (
    <section
      aria-roledescription="carousel"
      aria-label="Highlights"
      className="relative isolate overflow-hidden bg-brand-deep"
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
      onFocus={() => setHovering(true)}
      onBlur={() => setHovering(false)}
    >
      <div className="relative h-[86vh] min-h-[560px] max-h-[860px] w-full">
        {heroSlides.map((s, i) => {
          const active = i === index;
          return (
            <article
              key={s.title}
              aria-roledescription="slide"
              aria-label={`${i + 1} of ${heroSlides.length}`}
              aria-hidden={!active}
              className={cn("absolute inset-0 transition-opacity duration-700 motion-reduce:transition-none", active ? "opacity-100" : "pointer-events-none opacity-0")}
            >
              <div className="absolute inset-0 overflow-hidden">
                <img
                  src={s.image}
                  srcSet={`${variant(s.image, 900)} 900w, ${s.image} 1600w`}
                  sizes="100vw"
                  alt={s.alt}
                  decoding="async"
                  className="size-full object-cover"
                  style={{
                    objectPosition: s.position,
                    transform: active && !reduced ? "scale(1.06)" : "scale(1)",
                    transition: reduced ? "none" : "transform 7s ease-out",
                  }}
                  fetchPriority={i === 0 ? "high" : undefined}
                  loading={i === 0 ? "eager" : "lazy"}
                />
                <div className="absolute inset-0 bg-gradient-to-r from-black/60 via-black/25 to-transparent" aria-hidden />
              </div>

              <div className="container-wide relative flex h-full items-center">
                <div className="max-w-2xl py-16">
                  <span className="inline-flex items-center gap-2 text-[0.8125rem] font-semibold text-white/90">
                    <span className="h-px w-6 bg-orange" aria-hidden />
                    {s.eyebrow}
                  </span>
                  {i === 0 ? (
                    <h1 className="mt-5 text-4xl font-bold leading-[1.08] text-white drop-shadow-md sm:text-5xl lg:text-[3.5rem]">{s.title}</h1>
                  ) : (
                    <h2 className="mt-5 text-4xl font-bold leading-[1.08] text-white drop-shadow-md sm:text-5xl lg:text-[3.5rem]">{s.title}</h2>
                  )}
                  <p className="mt-5 max-w-xl text-lg leading-8 text-white/90">{s.text}</p>
                  <div className="mt-8 flex flex-wrap gap-3">
                    <a href={s.cta.href} tabIndex={active ? 0 : -1} className="btn-pill-orange">
                      {s.cta.label} <ArrowRight className="size-4" aria-hidden />
                    </a>
                    {s.secondary && (
                      <a href={s.secondary.href} tabIndex={active ? 0 : -1} className="btn-pill-ghost">
                        {s.secondary.label}
                      </a>
                    )}
                  </div>
                </div>
              </div>
            </article>
          );
        })}
      </div>

      {/* Side arrows */}
      <div className="pointer-events-none absolute inset-x-0 top-1/2 hidden -translate-y-1/2 md:block">
        <div className="mx-auto flex max-w-[96rem] items-center justify-between px-4">
          <button type="button" onClick={() => goTo(index - 1)} aria-label="Previous slide" className="hero-arrow pointer-events-auto">
            <ChevronLeft className="size-5" />
          </button>
          <button type="button" onClick={() => goTo(index + 1)} aria-label="Next slide" className="hero-arrow pointer-events-auto">
            <ChevronRight className="size-5" />
          </button>
        </div>
      </div>

      {/* Progress dots, counter and pause */}
      <div className="absolute inset-x-0 bottom-6 z-10">
        <div className="container-wide flex items-center gap-1">
          {heroSlides.map((s, i) => (
            <button
              key={s.title}
              type="button"
              onClick={() => goTo(i)}
              aria-label={`Show slide ${i + 1}: ${s.eyebrow}`}
              aria-current={i === index ? "true" : undefined}
              className="grid h-11 place-items-center px-1"
            >
              <span className={cn("relative block h-1.5 overflow-hidden rounded-full transition-all", i === index ? "w-12 bg-white/35" : "w-6 bg-white/40 hover:bg-white/70")}>
                {i === index && (
                  <span
                    key={`${index}-${running}`}
                    className="absolute inset-0 origin-left rounded-full bg-orange"
                    style={{ animation: running ? `heroProgress ${AUTOPLAY_MS}ms linear forwards` : "none", transform: running ? undefined : "scaleX(1)" }}
                  />
                )}
              </span>
            </button>
          ))}
          <span className="tabular ml-3 text-xs font-semibold text-white/85" aria-hidden>
            {String(index + 1).padStart(2, "0")} / {String(heroSlides.length).padStart(2, "0")}
          </span>
          {!reduced && (
            <button
              type="button"
              onClick={() => setPaused((p) => !p)}
              aria-label={paused ? "Play slideshow" : "Pause slideshow"}
              className="ml-3 grid size-11 place-items-center rounded-full border border-white/40 text-white hover:bg-white hover:text-brand-deep"
            >
              {paused ? <Play className="size-3.5" /> : <Pause className="size-3.5" />}
            </button>
          )}
        </div>
      </div>
    </section>
  );
}
